CREATE OR REPLACE FUNCTION public.admin_paid_tenants_page(_search text DEFAULT '',_sort text DEFAULT 'created_at',_ascending boolean DEFAULT false,_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ WITH filtered AS (SELECT to_jsonb(t) r FROM public.admin_list_tenant_accounts() t WHERE t.paid_amount>0 AND (_search='' OR concat_ws(' ',t.full_name,t.business_name,t.phone,t.cr_number,t.activity_type) ILIKE '%'||_search||'%')), paged AS (SELECT r FROM filtered ORDER BY CASE WHEN _ascending THEN r->>CASE WHEN _sort IN ('full_name','created_at','phone') THEN _sort ELSE 'created_at' END END ASC NULLS LAST,CASE WHEN NOT _ascending THEN r->>CASE WHEN _sort IN ('full_name','created_at','phone') THEN _sort ELSE 'created_at' END END DESC NULLS LAST,r->>'id' LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(r) FROM paged),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)); $$;
REVOKE ALL ON FUNCTION public.admin_paid_tenants_page(text,text,boolean,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_paid_tenants_page(text,text,boolean,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_paid_tenants_page(text,text,boolean,integer,integer)') IS NOT NULL AS paid_tenant_page_ready;